import os

def audit_file_permissions(directory: str) -> list[dict]:
    results = []
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            permissions = os.stat(file_path).st_mode & 0o777
            if permissions & 0o002:
                results.append({"path": file_path, "permissions": oct(permissions)})
    return results
